      reflect = true
      reflectionVector = reflectionVector + epsilon * (normal * (normal * ray))

    // Check if the intersection is refractive
    if materialProperties.refractiveIndex > 1 then
      refract = true
      refractedRay = calculateRefraction(ray, normal, materialProperties.refractiveIndex)

    // Recursively trace the reflected or refracted ray
    if reflect then
      recursiveRayTracing(reflectionVector, depth + 1)
    elif refract then
      recursiveRayTracing(refractedRay, depth + 1)
    else
      // Return the diffuse color at the intersection point
      return materialProperties.diffuseColor

function calculateIntersectionPoint(ray):
  // Compute the distance from the ray origin to the intersection point
  distance = rayOrigin.distanceToIntersectionPoint(ray.direction)

  // Return the intersection point
  return rayOrigin + ray.direction * distance

function calculateNormal(intersectionPoint):
  // Compute the normal at the intersection point
  normal = calculateNormalAtIntersectionPoint(intersectionPoint)

  // Return the normal
  return normal

function calculateReflectionVector(ray, normal):
  // Compute the reflection vector
  reflectionVector = ray.direction.reflect(normal)

  // Return the reflection vector
  return reflectionVector

function calculateRefraction(ray, normal, refractiveIndex):
  // Compute the refracted ray
  refractedRay = ray.direction.refract(normal, refractiveIndex)

  // Return the refracted ray
  return refractedRay

function recursiveRayTracing(ray, depth):
  // Base case: if the ray misses the scene or reaches the maximum depth
  if depth > MAX_DEPTH or missesScene(ray) then return

  // Continue tracing the ray recursively
  result = traceRay(ray, depth)

  // Accumulate the result
  accumulateResult(result)

  // Return the result
  return result
```
