Crea un nuevo script y llama a `GameController`. Agrega el siguiente código:
```csharp
using UnityEngine;

public class GameController : MonoBehaviour
{
    public GameObject[] gems;
    public int[] gemTypes;

    private int score;
    private int streak;

    void Start()
    {
        score = 0;
        streak = 0;
        ShuffleGems();
    }

    void ShuffleGems()
    {
        // Barajar las gemas
        for (int i = 0; i < gems.Length; i++)
        {
            int randomIndex = Random.Range(0, gems.Length);
            GameObject temp = gems[randomIndex];
            gems[randomIndex] = gems[i];
            gems[i] = temp;
        }
    }

    void Update()
    {
        // Verificar si se ha generado una secuencia de 3 o más gemas iguales
        CheckForMatches();
    }

    void CheckForMatches()
    {
        // Verificar las filas
        for (int y = 0; y < gems.GetLength(1); y++)
        {
            for (int x = 0; x < gems.GetLength(0); x++)
            {
                GameObject gem = gems[x, y];
                if (CanMakeMatch(gem))
                {
                    // Bunding match
                    MakeMatch(gem);
                }
            }
        }

        // Verificar las columnas
        for (int y = 0; y < gems.GetLength(1); y++)
        {
            for (int x = 0; x < gems.GetLength(0); x++)
            {
                GameObject gem = gems[x, y];
                if (CanMakeMatch(gem))
                {
                    // Bunding match
                    MakeMatch(gem);
                }
            }
        }
    }

    bool CanMakeMatch(GameObject gem)
    {
        // Verificar si hay al menos 2 gemas iguales al lado izquierdo
        if (x - 1 >= 0 && gems[x - 1, y].GetComponent<Gema>().GetType() == gem.GetComponent<Gema>().GetType())
        {
            return true;
        }

        // Verificar si hay al menos 2 gemas iguales al lado derecho
        if (x + 1 < gems.GetLength(0) && gems[x + 1, y].GetComponent<Gema>().GetType() == gem.GetComponent<Gema>().GetType())
        {
            return true;
        }

        // Verificar si hay al menos 2 gemas iguales arriba
        if (y - 1 >= 0 && gems[x, y - 1].GetComponent<Gema>().GetType() == gem.GetComponent<Gema>().GetType())
        {
            return true;
        }

        // Verificar si hay al menos 2 gemas iguales abajo
        if (y + 1 < gems.GetLength(1) && gems[x, y + 1].GetComponent<Gema>().GetType() == gem.GetComponent<Gema>().GetType())
        {
            return true;
        }

        return false;
    }

    void MakeMatch(GameObject gem)
    {
        // Eliminar la gema izquierda
        Destroy(gems[x - 1, y]);

        // Eliminar la gema derecha
        Destroy(gems[x + 1, y]);

        // Eliminar la gema arriba
        Destroy(gems[x, y - 1]);

        // Eliminar la gema abajo
        Destroy(gems[x, y + 1]);

        // Incrementar puntuación
        score += gem.GetComponent<Gema>().GetValue();

        // Verificar si se ha logrado un streak
        streak++;
    }
}
```
Este script maneja la lógica del juego, incluyendo la barajada de las gemas, la verificación de matches y la eliminación de las gemas.

