#include <log.h>

JNIEXPORT jint JNICALL Agency_VERSION(JNIEnv *env, jclass) {
    // Get the JVMTI agent object
    JVMTIEnv *env = (*env)->GetEnv(env, NULL);

    // Initialize JVMTI
    env->Initialize(NULL);

    // Set a callback to be called when a method is about to be executed
    env->SetMethodEntryEventHandler(NULL, onMethodEntry);

