// Message queue
managed_message_queue mpq(open_or_create, "mpq", 256, 256);

// Function to exchange data
void exchange_data() {
    // Request access to shared memory
    sem.post();

    // Receive message from server
    char buffer[256];
    mpq.receive(buffer, 256, 0);

    // Process received data
