```
#include <windows.h>
#include <iostream>
#include <cmath>
#include <random>

// Функция для вычисления значения интеграла методом прямоугольников
double integrateRectangles(double (*func)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += func(a + i * h);
    }
    return h * sum;
}

// Функция для вычисления значения интеграла методом трапеций
double integrateTrapezoids(double (*func)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.5 * (func(a) + func(b));
    for (int i = 1; i < n; i++) {
        sum += func(a + i * h);
    }
    return h * sum;
}

// Функция для вычисления значения интеграла методом Симпсона
double integrateSimpson(double (*func)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = func(a) + func(b);
    for (int i = 1; i < n; i++) {
        if (i % 2 == 1) {
            sum += 2 * func(a + i * h);
        } else {
            sum += 4 * func(a + i * h);
        }
    }
    return h / 3 * sum;
}

// Функция для вычисления значения интеграла по заданной формуле
double func(double x) {
    return x * x;
}

// Главная функция программы
int main() {
    // Создаем мьютекс для синхронизации вывода в переменную
    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);

    // Создаем переменную, в которую будет писаться результат вычислений
    double result = 0;

    // Создаем n потоков
    for (int i = 0; i < 4; i++) {
        // Создаем tread
        HANDLE thread = CreateThread(NULL, 0, &threadFunc, &mutex, i, NULL);
        // Создаем семафор для контроля потока
        HANDLE semaphore = CreateSemaphore(NULL, 0, 4, NULL);
        // Создаем случайный задержку
        Sleep(rand() % 1000 + 1);
        // Запускаем поток
        Sleep(rand() % 500 + 1);
        // Ожидаем, пока поток не закончит вычисления
        WaitForSingleObject(semaphore, INFINITE);
        // Получаем результат вычислений
        double localResult = 0;
        if (i == 0) {
            localResult = integrateRectangles(func, 0, 1, 1000);
        } else if (i == 1) {
            localResult = integrateTrapezoids(func, 0, 1, 1000);
        } else if (i == 2) {
            localResult = integrateSimpson(func, 0, 1, 1000);
        }
        // Синхронизируем вычисления
        WaitSingleObject(mutex, INFINITE);
        result += localResult;
        ReleaseMutex(mutex);
    }

    // Оставляем ожидание, пока не будут вычислены все потоки
    WaitForMultipleObjects(4, &thread[0], TRUE, INFINITE);

    // Выводим результат вычислений
    std::cout << "Result: " << result << std::endl;

    // Удаляем мьютекс
    ReleaseMutex(mutex);
    CloseHandle(mutex);

    return 0;
}

// Функция для потока
DWORD WINAPI threadFunc(LPVOID lpParam) {
    HANDLE *mutex = (HANDLE *)lpParam;
    HANDLE semaphore = CreateSemaphore(NULL, 1, 4, NULL);

    // Вычисляем значение ввода
    double result = 0;
    if (GetLastError() == 0) {
        // Выводим сообщение об ошибке
        std::cerr << "Error!" << std::endl;
    }

    // Ожидаем, пока не будет освобожден семафор
    WaitForSingleObject(semaphore, INFINITE);
    // Удаляем семафор
    CloseHandle(semaphore);

    return 0;
}
