```
import java.net.*;
import java.io.*;

public class NetworkSniffer {
  public static void main(String[] args) throws IOException {
    // Configuração do sniffer
    int port = 4477; // Porta onde o sniffer irá escutar
    System.out.println("Network Sniffer iniciado...");

    // Cria um socket que irá escutar na porta especificada
    ServerSocket serverSocket = new ServerSocket(port);
    System.out.println("Escutando na porta " + port);

    while (true) {
      // Aceita uma conexão
      Socket clientSocket = serverSocket.accept();
      System.out.println("Nova conexão estabelecida");

      // Cria um fluxo para ler e escrever dados
      InputStream inputStream = clientSocket.getInputStream();
      OutputStream outputStream = clientSocket.getOutputStream();

      // Lê dados do cliente
      byte[] buffer = new byte[1024];
      int bytes = inputStream.read(buffer);
      System.out.println("Recebido " + bytes + " bytes");

      // Processa os dados (neste exemplo, apenas imprime)
      String data = new String(buffer, 0, bytes);
      System.out.println("Dado recebido: " + data);

      // Responde ao cliente
      byte[] response = "Resposta do sniffer".getBytes();
      outputStream.write(response);
      outputStream.flush();
    }
  }
}
```
